// DisconnectClientByID will disconnect a client by its connection ID.
// Returns an error if the client is not found.
func (s *Server) DisconnectClientByID(id uint64) error {
	c := s.getClient(id)
	if c == nil {
		return fmt.Errorf("no such client id")
	}
	c.closeConnection(Kicked)
	return nil
}

// LDMClientByID will place a client into lame duck mode by its connection ID.
// Returns an error if the client is not found or cannot receive LDM info.
func (s *Server) LDMClientByID(id uint64) error {
	c := s.getClient(id)
	if c == nil {
		return fmt.Errorf("no such client id")
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	// Check if the client supports async INFO protocols and has completed initial handshake
	if c.opts.Protocol < ClientProtoInfo || !c.flags.isSet(firstPongSent) {
		return fmt.Errorf("client does not support async INFO or has not completed initial handshake")
	}

	// Generate and enqueue the LDM INFO message
	info := s.copyInfo()
	info.LameDuckMode = true
	// Clear URLs to prevent new connections
	info.ClientConnectURLs = info.ClientConnectURLs[:0]
	info.WSConnectURLs = info.WSConnectURLs[:0]

	c.enqueueProto(c.generateClientInfoJSON(info))
	return nil
}
