package main

import (
	"encoding/json"
	"fmt"
	"time"

	"github.com/nats-io/nats-server/v2/server"
	"github.com/nats-io/nats.go"
)

type KickClientReq struct {
	CID uint64 `json:"cid"`
}

type LDMClientReq struct {
	CID uint64 `json:"cid"`
}

func main() {
	// Start a NATS server with system account
	opts := &server.Options{
		Host:      "127.0.0.1",
		Port:      -1,
		SystemAccount: "SYSTEM",
	}

	s, err := server.NewServer(opts)
	if err != nil {
		panic(err)
	}

	go s.Start()

	if !s.ReadyForConnections(10 * time.Second) {
		panic("Server not ready")
	}

	defer s.Shutdown()

	// Connect a client
	nc, err := nats.Connect(fmt.Sprintf("nats://127.0.0.1:%d", s.Addr().(*net.TCPAddr).Port))
	if err != nil {
		panic(err)
	}
	defer nc.Close()

	// Get the client connection
	time.Sleep(100 * time.Millisecond)

	// Test DisconnectClientByID
	fmt.Println("Testing DisconnectClientByID...")

	// We need to get the CID of the connected client
	// This would typically be done through CONNZ or similar
	clients := s.Clients()
	if len(clients) == 0 {
		fmt.Println("No clients found")
		return
	}

	var cid uint64
	for c := range clients {
		cid = c.GetConnID()
		break
	}

	fmt.Printf("Found client with CID: %d\n", cid)

	// Try to disconnect the client
	err = s.DisconnectClientByID(cid)
	if err != nil {
		fmt.Printf("Error disconnecting client: %v\n", err)
	} else {
		fmt.Println("Client disconnected successfully")
	}

	// Test with non-existent client
	err = s.DisconnectClientByID(999999)
	if err != nil {
		fmt.Printf("Expected error for non-existent client: %v\n", err)
	}

	// Test LDMClientByID
	fmt.Println("\nTesting LDMClientByID...")

	// Connect another client
	nc2, err := nats.Connect(fmt.Sprintf("nats://127.0.0.1:%d", s.Addr().(*net.TCPAddr).Port))
	if err != nil {
		panic(err)
	}
	defer nc2.Close()

	time.Sleep(100 * time.Millisecond)

	clients = s.Clients()
	var cid2 uint64
	for c := range clients {
		cid2 = c.GetConnID()
		break
	}

	fmt.Printf("Found client with CID: %d\n", cid2)

	// Try to put client in LDM mode
	err = s.LDMClientByID(cid2)
	if err != nil {
		fmt.Printf("Error putting client in LDM: %v\n", err)
	} else {
		fmt.Println("Client LDM signal sent successfully")
	}

	// Test with non-existent client
	err = s.LDMClientByID(999999)
	if err != nil {
		fmt.Printf("Expected error for non-existent client: %v\n", err)
	}

	fmt.Println("\nAll tests completed!")
}
